def rule_page1_company_common_stock_exchange_sequence(doc: dict) -> list[dict]:
    """Match page-1 sequences containing company cover info, common stock, symbol, and exchange."""
    import re
    try:
        texts = doc.get("texts", [])
        out = []
        for i in range(len(texts)):
            if texts[i].get("page_no") != 1:
                continue
            window = texts[i:min(len(texts), i + 20)]
            joined = " ".join((w.get("text") or "") + " " + (w.get("text_span") or "") for w in window)
            if re.search(r"Common Stock", joined, re.I) and re.search(r"NASDAQ|NYSE|New York Stock Exchange|Nasdaq", joined, re.I):
                if re.search(r"\b[A-Z]{1,6}(?:\d+[A-Z]*)?(?:[./-][A-Z0-9]+)?\b", joined):
                    out.extend(window)
        return out
    except Exception:
        return []

def rule_page1_symbol_exchange_triplet_table(doc: dict) -> list[dict]:
    """Match 3-column page-1 tables with class, symbol, and exchange columns."""
    import re
    try:
        out = []
        for s in doc.get("texts", []):
            if s.get("label") != "table" or s.get("page_no") != 1:
                continue
            td = s.get("table_data") or {}
            if td.get("num_cols") == 3:
                cells = td.get("cells") or []
                joined = " | ".join((c.get("text") or "") for c in cells)
                if re.search(r"Title of each class", joined, re.I) and re.search(r"Trading Symbol", joined, re.I) and re.search(r"exchange", joined, re.I):
                    out.append(s)
        return out
    except Exception:
        return []

def rule_page1_cover_page_security_cluster(doc: dict) -> list[dict]:
    """Match dense page-1 cover-page clusters containing company identity plus Section 12(b) registration info."""
    import re
    try:
        texts = doc.get("texts", [])
        out = []
        for i, s in enumerate(texts):
            blob = (s.get("text") or "") + " " + (s.get("text_span") or "")
            if s.get("page_no") == 1 and re.search(r"Exact name of registrant|Commission File|Employer Identification", blob, re.I):
                window = texts[max(0, i - 5):min(len(texts), i + 20)]
                joined = " ".join((w.get("text") or "") + " " + (w.get("text_span") or "") for w in window)
                if re.search(r"Section 12\(b\)|Trading Symbol|exchange on which registered|NASDAQ|NYSE|New York Stock Exchange", joined, re.I):
                    out.extend(window)
        return out
    except Exception:
        return []

